export function Wordmark({ completo = true, className = '' }: { completo?: boolean; className?: string }) {
  return (
    <svg
      className={className}
      viewBox={completo ? '-1.5 -1.5 479 140' : '-1.5 -1.5 479 104'}
      role="img"
      aria-label={completo ? MARCA.nomeCompleto : MARCA.nome}
      fill="currentColor"
    >
      <g stroke="currentColor" strokeWidth="2" strokeLinejoin="round">
        {LETRAS.map((d) => (
          <path key={d} d={d} />
        ))}
      </g>
      <circle cx="132.4" cy="79.5" r="10.5" fill="var(--brand)" />
      {completo && <path d={CONCURSOS} />}
    </svg>
  );
}

// Ícone do app (o mesmo do favicon e do PWA): T branco e ponto vermelho.
export function AppIcon({ size = 40, className = '' }: { size?: number; className?: string }) {
  return (
    <svg className={className} width={size} height={size} viewBox="0 0 100 100" aria-hidden="true">
      <rect width="100" height="100" rx="20" fill="var(--ink)" />
      <g fill="#fff" stroke="#fff" strokeWidth="1.5" strokeLinejoin="round">
        <path d="M19.8 25.8 H80.2 V39.9 H19.8 Z" />
        <path d="M40.8 52.4 L54.2 44.3 V80.1 H40.8 Z" />
      </g>
      <circle cx="68.1" cy="64.8" r="6.9" fill="var(--brand)" />
    </svg>
  );
}

export default function Brand({ light = false, compact = false, caption }: { light?: boolean; compact?: boolean; caption?: string }) {
  return (
    <div className={`brand${light ? ' brand-light' : ''}${compact ? ' brand-compact' : ''}`}>
      <Wordmark completo={!compact} className="brand-wordmark" />
      {caption && <small>{caption}</small>}
    </div>
  );
}
